function NOVELTY_SCORE(S, x):
    if S is empty: return +infinity
    best <- +infinity
    for each s in S:
        best <- min(best, dist(x, s))
    return best

function IS_NOVEL(eps, S, x):
    return eps <= NOVELTY_SCORE(S, x)

