function DIRECTED_HAUSDORFF(A, B):
    return max over a in A of (min over b in B of dist(a, b))

function HAUSDORFF_DIST(A, B):
    return max(DIRECTED_HAUSDORFF(A, B), DIRECTED_HAUSDORFF(B, A))

function IS_NOVEL_SET(eps, family, A):
    for each B in family:
        if HAUSDORFF_DIST(A, B) < eps: return false
    return true

